insert into public.documentos (coleccion,id,data) values ('citaciones','demo-t1','{"id": "demo-t1", "citado": "[EJEMPLO] Secretario de Gobierno", "tema": "Seguridad en la zona rural", "sesionId": "demo-s21", "bancada": "Cambio Radical", "proponentes": ["molina"], "sesionOrigen": "demo-s10", "fechaEnvio": "2026-11-03", "enviada": false, "respondida": false, "cuestionario": "¿Cuántos casos de hurto rural se reportaron en el último año y en qué veredas?\n¿Qué acciones se han coordinado con la Policía y el Ejército?\n¿Con qué presupuesto cuenta el plan de seguridad rural en 2026?\n¿Qué resultados tiene el programa de frentes de seguridad?", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
