insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g1','{"id": "demo-g1", "numero": 1, "anio": 2026, "tipo": "resolucion", "titulo": "[EJEMPLO] Resolución 001 de 2026: por la cual se fija el horario de las sesiones ordinarias", "resumen": "Las sesiones de la plenaria serán a las 6:00 p. m. y las de comisiones a las 4:00 p. m., salvo convocatoria distinta.", "texto": "RESOLUCIÓN N.º 001 DE 2026\n\nLA MESA DIRECTIVA DEL CONCEJO MUNICIPAL DE MONTENEGRO,\n\nRESUELVE:\n\nARTÍCULO PRIMERO. Las sesiones ordinarias de la plenaria se realizarán a las 6:00 p. m.\n\nARTÍCULO SEGUNDO. Las sesiones de las comisiones permanentes se realizarán a las 4:00 p. m.\n\nARTÍCULO TERCERO. La presente resolución rige desde su publicación.\n\n[Texto de ejemplo]", "fecha": "2026-02-12T21:00:00.000Z", "proyectoId": "", "sesionId": "", "vigenteHasta": "", "pdfUrl": "", "corrigeA": "", "publicadoPor": "", "hash": "d86ffe7a110b217cd11cdfc8bbee8273905d4e75326176d976e90142f9b23477", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g2','{"id": "demo-g2", "numero": 2, "anio": 2026, "tipo": "acuerdo", "titulo": "[EJEMPLO] Acuerdo 007 de 2026: por medio del cual se institucionaliza la Semana de la Juventud Montenegrina", "resumen": "Cada año, en agosto, el municipio celebrará una semana dedicada a los jóvenes, con actividades culturales, deportivas y de participación.", "texto": "ACUERDO MUNICIPAL N.º 007 DE 2026\n\n“Por medio del cual se institucionaliza la Semana de la Juventud Montenegrina”\n\nEL CONCEJO MUNICIPAL DE MONTENEGRO, QUINDÍO, en uso de sus atribuciones constitucionales y legales,\n\nACUERDA:\n\nARTÍCULO PRIMERO. Institucionalícese la Semana de la Juventud Montenegrina, que se celebrará la segunda semana de agosto de cada año.\n\nARTÍCULO SEGUNDO. La Administración Municipal coordinará las actividades con la Plataforma Municipal de Juventudes.\n\nARTÍCULO TERCERO. El presente acuerdo rige a partir de su publicación.\n\n[Texto de ejemplo]", "fecha": "2026-09-03T15:20:00.000Z", "proyectoId": "demo-p3", "sesionId": "demo-s10", "vigenteHasta": "", "pdfUrl": "", "corrigeA": "", "publicadoPor": "", "hash": "bc8766d71f8f318e08e5191da684da14092f51f534dff70e0248cb9a49f5a26d", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g3','{"id": "demo-g3", "numero": 3, "anio": 2026, "tipo": "proyecto", "titulo": "[EJEMPLO] Proyecto de Acuerdo 011 de 2026: presupuesto general de rentas y gastos para la vigencia 2027", "resumen": "Se radicó el proyecto de presupuesto 2027. Lo estudia la Comisión de Presupuesto y Hacienda; la comunidad puede conocerlo y opinar.", "texto": "Proyecto de Acuerdo radicado el 1 de octubre de 2026 por el Alcalde Municipal.\n\nValor total del presupuesto: $ 38.500 millones.\n\nPonentes: Rafael Guerra y Luz Miryam Coronado.\n\n[Texto de ejemplo]", "fecha": "2026-10-02T14:00:00.000Z", "proyectoId": "demo-p2", "sesionId": "", "vigenteHasta": "", "pdfUrl": "", "corrigeA": "", "publicadoPor": "", "hash": "c6f138d70e7a7ba35df5fb06fdaf13eb84001a2281702bbb7bacef5457231cbc", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g4','{"id": "demo-g4", "numero": 4, "anio": 2026, "tipo": "acta", "titulo": "[EJEMPLO] Acta EJ-011: sesión de la Comisión de Presupuesto y Hacienda del 24 de octubre de 2026", "resumen": "Se dio primer debate al presupuesto 2027 y se escuchó a la Secretaria de Hacienda sobre el recaudo del predial.", "texto": "ACTA EJ-011\n\nFecha: 24 de octubre de 2026, 6:00 p. m.\nLugar: Recinto del Concejo.\n\n1. Llamado a lista y verificación del quórum.\n2. Aprobación del orden del día.\n3. Primer debate al Proyecto de Acuerdo 011 de 2026.\n4. Intervención de la Secretaria de Hacienda.\n\n[Texto de ejemplo]", "fecha": "2026-10-30T23:40:00.000Z", "proyectoId": "", "sesionId": "demo-s11", "vigenteHasta": "", "pdfUrl": "", "corrigeA": "", "publicadoPor": "", "hash": "8c9b847483c1f4bd8b980186295eb5cb772cc2338ba17da9a9120685c0af337f", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g5','{"id": "demo-g5", "numero": 5, "anio": 2026, "tipo": "aviso", "titulo": "[EJEMPLO] Inscripciones abiertas para intervenir en la sesión plenaria del 6 de noviembre", "resumen": "Cualquier persona puede inscribirse en «Participa» para hablar en la sesión sobre la política de turismo cafetero.", "texto": "La Secretaría General informa que están abiertas las inscripciones para intervenir en la sesión plenaria del 6 de noviembre de 2026, en la que se dará segundo debate al Proyecto de Acuerdo 010 de 2026 (turismo cafetero).\n\nLas inscripciones se reciben en la sección «Participa» de esta plataforma.", "fecha": "2026-11-03T14:00:00.000Z", "proyectoId": "", "sesionId": "demo-s20", "vigenteHasta": "2026-11-06", "pdfUrl": "", "corrigeA": "", "publicadoPor": "", "hash": "a4c8311ff24a6bcc3d5d7e90fb978457e5f6fac7aa0f6a293be6255a0d697b68", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
insert into public.documentos (coleccion,id,data) values ('gaceta','demo-g6','{"id": "demo-g6", "numero": 6, "anio": 2026, "tipo": "erratas", "titulo": "[EJEMPLO] Fe de erratas a la publicación N.º 003 de 2026", "resumen": "Se corrige el valor total del presupuesto publicado.", "texto": "En la publicación N.º 003 de 2026 — «Proyecto de Acuerdo 011 de 2026», publicada el 2 de octubre de 2026:\n\nDonde dice: «$ 38.500 millones»\nDebe decir: «$ 38.050 millones»", "fecha": "2026-11-04T13:00:00.000Z", "proyectoId": "", "sesionId": "", "vigenteHasta": "", "pdfUrl": "", "corrigeA": "demo-g3", "publicadoPor": "", "hash": "3a41ed1853c11c42363ad148f8bcff2af36ff15d721864b12cee92c0701e6de8", "demo": true}'::jsonb) on conflict (coleccion,id) do update set data=excluded.data, updated_at=now();
